/* Tekrar havuzu: ten-pastperf, ten-perfect, ten-future, ten-continuous, ten-timeclause */
PRACTICE.push(
  {id:"r-ten-pastperf-01", sub:"ten-pastperf", from:["tenses-01"], q:"By the time the Spanish conquistadors arrived in Central America, the Maya civilisation ---- much of its former political power.", o:["had lost","loses","has lost","will have lost","is losing"], a:0, e:"“By the time + Simple Past” kalıbında ana cümle, varıştan önce tamamlanmış durumu Past Perfect ile verir. “has lost” bugüne bağlanır, geçmişteki “arrived” referansıyla uyuşmaz."},
  {id:"r-ten-pastperf-02", sub:"ten-pastperf", from:["tenses-01","tenses-17"], q:"The economist ---- the collapse of the housing market long before most of his colleagues ---- that anything was wrong.", o:["predicts / had realised","predicted / had realised","has predicted / realise","was predicting / have realised","had predicted / realised"], a:4, e:"Önce gerçekleşen tahmin Past Perfect, sonra gelen fark ediş Simple Past olur. “predicted / had realised” sırayı tersine çevirir; meslektaşların fark edişini tahminden önceye atar."},
  {id:"r-ten-pastperf-03", sub:"ten-pastperf", from:["tenses-07"], q:"Scarcely ---- the results of the clinical trial when other laboratories began questioning its methodology.", o:["the researchers had published","had the researchers published","did the researchers publish","have the researchers published","the researchers published"], a:1, e:"“Scarcely … when” cümle başında devrik yapı ve Past Perfect ister: Scarcely had + özne + V3. “the researchers had published” zamanı doğru ama devrik yapı kurulmadığı için yanlıştır."},
  {id:"r-ten-pastperf-04", sub:"ten-pastperf", from:["tenses-01","tenses-12"], q:"After the committee ---- all the evidence, it ---- that the factory was responsible for the pollution.", o:["had reviewed / concluded","reviews / concluded","has reviewed / had concluded","was reviewing / concludes","reviewed / has concluded"], a:0, e:"“After + Past Perfect, Simple Past” kalıbında önce biten inceleme Past Perfect, ardından gelen karar Simple Past olur. “has reviewed / had concluded” sırayı tersine çevirir ve Present Perfect geçmiş anlatıya uymaz."},
  {id:"r-ten-pastperf-05", sub:"ten-pastperf", from:["tenses-07"], q:"No sooner had the new president taken office ---- a severe economic crisis hit the country.", o:["that","when","then","than","as"], a:3, e:"“No sooner had … ” yapısı her zaman “than” ile tamamlanır. “when” ise “Hardly / Scarcely had …” yapısına aittir; bu iki kalıbı karıştırmak tipik bir tuzaktır."},
  {id:"r-ten-pastperf-06", sub:"ten-pastperf", from:["tenses-17"], q:"The spokesperson announced that the company ---- its production targets in each of the previous three years.", o:["exceeds","had exceeded","has been exceeding","will exceed","would exceed"], a:1, e:"Ana fiil “announced” geçmişte olduğu için ondan önceki yıllarda gerçekleşen eylem Past Perfect'e kayar; “the previous three years” da geçmişteki bir referans noktasını gösterir. “has been exceeding” bugüne bağlanır, geçmiş anlatımla uyuşmaz."},
  {id:"r-ten-pastperf-07", sub:"ten-pastperf", from:["tenses-12"], q:"When the drought finally ended in 2012, farmers in the region ---- for rain for almost four years.", o:["had been waiting","waited","have been waiting","were waiting","will have waited"], a:0, e:"Geçmişteki bir olaya (ended) kadar bir süredir devam eden eylem “for almost four years” ile Past Perfect Continuous alır. “have been waiting” bugüne kadar süren eylem içindir, 2012'deki bir referansla uyuşmaz."},
  {id:"r-ten-pastperf-08", sub:"ten-pastperf", from:["tenses-12","tenses-01"], q:"The ancient manuscript ---- in a monastery library for centuries before a visiting scholar finally ---- its significance in 1844.", o:["lay / recognises","had lain / recognised","has lain / recognised","was lying / had recognised","lies / has recognised"], a:1, e:"1844'teki fark edişten önce yüzyıllarca süren durum Past Perfect, fark ediş ise “in 1844” nedeniyle Simple Past olur. “was lying / had recognised” fark edişi daha önceye atarak sırayı bozar."},
  {id:"r-ten-pastperf-09", sub:"ten-pastperf", from:["tenses-12"], q:"Before the Suez Canal opened in 1869, ----.", o:["trade between Europe and Asia will depend on the long route around Africa","ships sailing from Europe to Asia had been forced to travel around the southern tip of Africa for centuries","merchants have complained about the long journey around Africa","the journey from London to Bombay takes about three months","the canal has reduced shipping times dramatically"], a:1, e:"“Before + Simple Past” geçmiş bağlam kurar; kanaldan önce yüzyıllarca süren durum Past Perfect ile anlatılır. “merchants have complained” Present Perfect olduğu için 1869 öncesine ait bir durumu anlatamaz."},
  {id:"r-ten-pastperf-10", sub:"ten-pastperf", from:["tenses-01","tenses-12"], q:"The fire ---- for several hours by the time the first fire engines ---- the remote village.", o:["has been burning / reach","burned / have reached","had been burning / reached","was burning / had reached","burns / will reach"], a:2, e:"“By the time + Simple Past” ile ana cümlede o ana kadar süregelen eylem Past Perfect Continuous alır. “was burning / had reached” itfaiyenin varışını yangından önceye atar; sıra ters kurulmuştur."},
  {id:"r-ten-pastperf-11", sub:"ten-pastperf", from:["tenses-07"], q:"Hardly ---- the dam when engineers ---- serious cracks in its foundation.", o:["have they completed / notice","they had completed / have noticed","did they complete / had noticed","had they completed / noticed","they completed / were noticing"], a:3, e:"“Hardly … when” devrik yapı ve Past Perfect ister; “when” sonrası Simple Past olur: Hardly had they completed … when engineers noticed. “they had completed / have noticed” devrik değildir ve ikinci boşluk geçmiş anlatıma uymaz."},
  {id:"r-ten-pastperf-12", sub:"ten-pastperf", from:["tenses-12"], q:"Until the discovery of X-rays in 1895, doctors ---- no way of seeing inside the human body without surgery.", o:["will have","have had","have","had had","are having"], a:3, e:"“Until 1895” geçmişteki bir noktaya kadar süren durumu anlatır; bu nedenle Past Perfect (had had) gerekir. “have had” bugüne uzanan süreci anlatır, geçmişte biten bir dönemle uyuşmaz."},
  {id:"r-ten-pastperf-13", sub:"ten-pastperf", from:["tenses-12","tenses-17"], q:"The delegates looked exhausted when they arrived at the summit, as they ---- through the night to reach a preliminary agreement.", o:["are negotiating","have negotiated","negotiate","will be negotiating","had been negotiating"], a:4, e:"Geçmişteki bir andan (arrived) önce süregelen ve sonucu görülen eylem (yorgunluk) Past Perfect Continuous ile anlatılır. “have negotiated” bugüne bağlanır, “looked / arrived” geçmiş bağlamıyla uyuşmaz."},
  {id:"r-ten-pastperf-14", sub:"ten-pastperf", from:["tenses-01"], q:"Once the archaeologists ---- the tomb, they realised that robbers ---- it centuries earlier.", o:["opened / had looted","had opened / have looted","have opened / have looted","open / were looting","were opening / loot"], a:0, e:"Mezarın açılması ve fark ediş geçmişte ardışık olaylardır (Simple Past); yağma ise bunlardan çok önce olduğu için Past Perfect alır. “had opened / have looted” ikinci boşlukta Present Perfect kullandığı için geçmiş anlatımla çelişir."},
  {id:"r-ten-pastperf-15", sub:"ten-pastperf", from:["tenses-01"], q:"By the time the United Nations was founded in 1945, the Second World War ---- more than sixty million lives.", o:["claims","had claimed","has claimed","was claiming","will have claimed"], a:1, e:"“By the time + Simple Past” ile o ana kadar tamamlanmış kayıp Past Perfect ile verilir. “will have claimed” Future Perfect'tir ve “by the time + present” ile kullanılır; burada fiil geçmiş zamandadır (was founded)."},
  {id:"r-ten-pastperf-16", sub:"ten-pastperf", from:["tenses-17","tenses-01"], q:"The historian explained that the city ---- an important trading centre long before the Romans ---- it in the first century BC.", o:["had been / conquered","has been / conquer","was / had conquered","is / have conquered","would be / conquered"], a:0, e:"“explained” anlatımı geçmişe kaydırır; Romalılardan önceki durum Past Perfect, fetih ise Simple Past olur. “was / had conquered” fethi daha önceye atarak sırayı tersine çevirir."},
  {id:"r-ten-pastperf-17", sub:"ten-pastperf", from:["tenses-01","tenses-12"], q:"It was only after the bridge ---- to traffic that engineers identified a serious flaw in its design.", o:["is opened","has been opened","had been opened","will be opened","would have opened"], a:2, e:"“only after” ile geçmişte önce gerçekleşen eylem Past Perfect alır; köprü açılan taraf olduğu için edilgen yapı (had been opened) gerekir. “has been opened” Present Perfect olduğundan geçmiş anlatımla (was, identified) uyuşmaz."},
  {id:"r-ten-pastperf-18", sub:"ten-pastperf", from:["tenses-01","tenses-17"], passage:"For centuries, scholars had tried without success to read Egyptian hieroglyphs. The breakthrough came only after French soldiers discovered the Rosetta Stone in 1799. The stone carried the same decree in three scripts, one of which was ancient Greek, a language that scholars could already read. Even so, progress was slow. By the time Jean-François Champollion announced his decipherment in 1822, several researchers (1) ---- partial translations, but none of them had understood that hieroglyphs combined sound signs with symbols representing ideas. Champollion's insight transformed Egyptology and made thousands of previously unreadable texts available to modern study.", blank:1, q:"(1) numaralı boşluğa uygun ifadeyi seçiniz.", o:["are already proposing","have already proposed","will already propose","had already proposed","already propose"], a:3, e:"“By the time + Simple Past (announced)” kalıbı ana cümlede Past Perfect ister; devamındaki “had understood” da bunu destekler. “have already proposed” Present Perfect olduğu için 1822'deki geçmiş referansla uyuşmaz."},
  {id:"r-ten-pastperf-19", sub:"ten-pastperf", from:["tenses-12","tenses-01"], q:"The villagers ---- the approaching storm on the radio for days, so they ---- their livestock to higher ground before the floods came.", o:["were followed / have moved","have followed / move","had been following / had moved","follow / had been moved","will follow / moved"], a:2, e:"Selden (came) önce günlerce süren takip Past Perfect Continuous, selden önce tamamlanan taşıma Past Perfect ile anlatılır. “were followed / have moved” edilgen yapı anlamı bozar, Present Perfect de geçmiş anlatıma uymaz."},
  {id:"r-ten-pastperf-20", sub:"ten-pastperf", from:["tenses-01"], q:"When the police finally arrived at the bank, the robbers ----, taking nearly two million dollars with them.", o:["are already escaping","already escape","have already escaped","will already have escaped","had already escaped"], a:4, e:"Polisin varışından önce tamamlanmış kaçış Past Perfect ile verilir; “already” de tamamlanmayı vurgular. “have already escaped” bugüne bağlanır, “arrived” geçmiş referansıyla uyuşmaz."},
  {id:"r-ten-pastperf-21", sub:"ten-pastperf", from:["tenses-01","tenses-17"], q:"Only when the researchers ---- the analysis did they publish their findings in a leading journal.", o:["had completed","have completed","complete","will complete","are completing"], a:0, e:"Yayından önce tamamlanan analiz, geçmiş bağlamda (did they publish) Past Perfect alır. “have completed” Present Perfect olduğu için geçmişteki yayın olayıyla zaman uyumu kurmaz."},
  {id:"r-ten-pastperf-22", sub:"ten-pastperf", from:["tenses-17"], q:"Not until the auditors ---- the accounts did the board realise how serious the company's losses were.", o:["examine","have examined","had examined","will examine","would have examined"], a:2, e:"Geçmişte önce gerçekleşen inceleme Past Perfect alır; ana cümledeki “did … realise” geçmiş zamanı gösterir. “have examined” Present Perfect olduğundan geçmişte kalan bu olay dizisine uymaz."},
  {id:"r-ten-pastperf-23", sub:"ten-pastperf", from:["tenses-12","tenses-17"], q:"The patient ---- from chronic headaches for years before doctors finally ---- that a rare genetic condition was responsible.", o:["suffers / will discover","has suffered / discover","suffered / had discovered","was suffering / have discovered","had been suffering / discovered"], a:4, e:"Keşiften önce yıllarca süren rahatsızlık Past Perfect Continuous, keşif ise Simple Past ile verilir. “suffered / had discovered” keşfi rahatsızlıktan önceye atar; sıra ters kurulmuştur."},
  {id:"r-ten-pastperf-24", sub:"ten-pastperf", from:["tenses-01"], q:"----, the ship had already sunk beneath the waves.", o:["Once the captain issues a distress signal","As soon as the storm will calm down","Until the crew has abandoned the vessel","While the coast guard is sending help","By the time the rescue helicopters reached the scene"], a:4, e:"Ana cümledeki Past Perfect (had already sunk), geçmiş zamanlı bir “By the time” yan cümlesiyle uyumludur. Diğer seçenekler şimdiki ya da gelecek zaman içerir; “As soon as … will” ayrıca zaman bağlacından sonra will kullandığı için yanlıştır."},
  {id:"r-ten-pastperf-25", sub:"ten-pastperf", from:["tenses-01","tenses-07"], q:"The treaty ---- only a few weeks earlier when fighting broke out again along the border.", o:["was being signed","has been signed","had been signed","is signed","will have been signed"], a:2, e:"Çatışmanın yeniden başlamasından (broke out) birkaç hafta önce tamamlanan imza Past Perfect Passive ile anlatılır. “was being signed” imzanın o anda sürdüğünü anlatır, “a few weeks earlier” ile çelişir."},
  {id:"r-ten-pastperf-26", sub:"ten-pastperf", from:["tenses-07"], q:"No sooner ---- the new tax than thousands of people ---- to the streets in protest.", o:["the government had announced / take","had the government announced / took","did the government announce / had taken","has the government announced / have taken","the government announced / were taking"], a:1, e:"“No sooner … than” devrik yapı ve Past Perfect ister; “than” sonrası Simple Past gelir. “the government had announced / take” zamanı doğru verse de devrik yapıyı kurmaz ve ikinci boşluk geçmiş zamanda değildir."},
  {id:"r-ten-pastperf-27", sub:"ten-pastperf", from:["tenses-12","tenses-01"], q:"Before she became the first woman to win a Nobel Prize, Marie Curie ---- years studying radioactive materials in a poorly equipped laboratory.", o:["will have spent","has spent","spends","had spent","is spending"], a:3, e:"“Before + Simple Past” kalıbında daha önce tamamlanan eylem Past Perfect alır. “will have spent” Future Perfect olup geçmişteki bir olayla (became) kullanılamaz."},
  {id:"r-ten-perfect-01", sub:"ten-perfect", from:["tenses-02","tenses-06"], q:"Over the past two decades, the cost of solar panels ---- by nearly 90 percent, making renewable energy competitive with fossil fuels.", o:["has fallen","fell","had fallen","was falling","will fall"], a:0, e:"“Over the past two decades” geçmişten bugüne uzanan bir dönemi gösterir ve Present Perfect ister. “had fallen” için geçmişte ikinci bir referans noktası gerekir, cümlede yok."},
  {id:"r-ten-perfect-02", sub:"ten-perfect", from:["w2-01","tenses-02"], q:"Since the city ---- its bicycle-sharing scheme, traffic congestion in the centre ---- noticeably.", o:["launched / had decreased","has launched / decreased","launched / has decreased","launches / decreases","had launched / was decreasing"], a:2, e:"“Since” yan cümlesi başlangıç noktasını Simple Past ile, ana cümle bugüne uzanan sonucu Present Perfect ile verir. “has launched / decreased” zamanları yer değiştirmiştir."},
  {id:"r-ten-perfect-03", sub:"ten-perfect", from:["tenses-02","w2-01"], q:"The Hubble Space Telescope ---- into orbit in 1990, and since then it ---- more than a million observations.", o:["had been launched / makes","has been launched / made","was launched / has made","was launching / had made","is launched / was making"], a:2, e:"“in 1990” belli bir geçmiş zaman olduğu için Simple Past (edilgen) ister; “since then” ise bugüne uzanan süreci Present Perfect ile verir. “has been launched / made” belli geçmiş zamanla Present Perfect kullandığı için yanlıştır."},
  {id:"r-ten-perfect-04", sub:"ten-perfect", from:["tenses-06"], q:"Up to now, no country ---- to eliminate malaria completely without a sustained public-health campaign.", o:["had managed","managed","has managed","was managing","manages"], a:2, e:"“Up to now” (şimdiye kadar) Present Perfect'in tipik zarfıdır. “managed” bitmiş bir geçmişi anlatır ve bugüne kadar süren dönemi kapsamaz."},
  {id:"r-ten-perfect-05", sub:"ten-perfect", from:["tenses-16"], q:"It is the second time this year that the central bank ---- interest rates in response to rising inflation.", o:["has raised","raised","had raised","raises","was raising"], a:0, e:"“It is the first/second time that …” kalıbı Present Perfect ister. “had raised” ancak “It was the second time” ile kullanılabilir."},
  {id:"r-ten-perfect-06", sub:"ten-perfect", from:["tenses-16"], q:"It was the first time that researchers ---- a live specimen of the rare deep-sea fish in its natural habitat.", o:["had filmed","have filmed","film","were filming","will film"], a:0, e:"“It was the first time that …” geçmişe aittir ve Past Perfect ister. “have filmed” ancak “It is the first time” kalıbıyla kullanılır; bu fark kalıbın en sık kullanılan tuzağıdır."},
  {id:"r-ten-perfect-07", sub:"ten-perfect", from:["tenses-02","w2-01"], q:"The Human Genome Project ---- in 2003, and since then the cost of sequencing a genome ---- from billions of dollars to a few hundred.", o:["has been completed / dropped","was completed / has dropped","had been completed / drops","is completed / had dropped","was completing / was dropping"], a:1, e:"“in 2003” Simple Past, “since then” ise Present Perfect ister. “has been completed / dropped” belli geçmiş zamanla Present Perfect kullanır, bu yüzden yanlıştır."},
  {id:"r-ten-perfect-08", sub:"ten-perfect", from:["tenses-06","tenses-11"], q:"Researchers ---- the long-term effects of the drug for only five years, so it is too early to draw firm conclusions.", o:["were studying","studied","had been studying","have been studying","will study"], a:3, e:"“for only five years” ve “it is too early” geçmişte başlayıp hâlâ süren bir süreci gösterir: Present Perfect Continuous. “had been studying” geçmişteki bir referans noktası ister, cümle ise şimdiki zamana bağlıdır."},
  {id:"r-ten-perfect-09", sub:"ten-perfect", from:["tenses-02","w2-01"], q:"The number of international students in the country ---- steadily since 2010, although it ---- slightly last year because of new visa rules.", o:["has risen / fell","rose / has fallen","had risen / has fallen","has risen / has fallen","was rising / had fallen"], a:0, e:"“since 2010” Present Perfect, “last year” ise belli geçmiş zaman olduğundan Simple Past ister. “has risen / has fallen” ikinci boşlukta “last year” ile Present Perfect kullandığı için yanlıştır."},
  {id:"r-ten-perfect-10", sub:"ten-perfect", from:["tenses-06"], q:"The new drug ---- by regulators yet, so doctors are still not allowed to prescribe it.", o:["had not been approved","was not being approved","has not been approved","is not being approved","will not be approved"], a:2, e:"“yet” olumsuz cümlede Present Perfect'in tipik zarfıdır ve sonucu bugünü etkiler (are still not allowed). “had not been approved” geçmişte bir referans noktası ister, cümle ise şimdiki zamana bağlıdır."},
  {id:"r-ten-perfect-11", sub:"ten-perfect", from:["tenses-06","tenses-11"], q:"Although astronomers ---- dozens of exoplanets in the habitable zone so far, none of them ---- to support life yet.", o:["were identifying / had been shown","identified / was shown","had identified / is shown","have identified / has been shown","identify / will be shown"], a:3, e:"“so far” ve “yet” iki boşlukta da Present Perfect ister; gezegenler gösterilen taraf olduğundan ikinci boşluk edilgendir. “identified / was shown” bitmiş geçmiş anlatır ve bu zarflarla uyuşmaz."},
  {id:"r-ten-perfect-12", sub:"ten-perfect", from:["tenses-02"], q:"Since its foundation in 1870, the museum ---- one of the largest fossil collections in the country, attracting researchers from all over the world.", o:["will house","housed","had housed","is housing","has housed"], a:4, e:"“Since its foundation in 1870” geçmişten bugüne süren bir durumu gösterir; Present Perfect gerekir. “housed” bitmiş bir geçmiş anlatır, “since” ile kullanılmaz."},
  {id:"r-ten-perfect-13", sub:"ten-perfect", from:["tenses-02","w2-01"], q:"Two years ago, the company ---- a new recycling programme, which ---- its waste output by a third since then.", o:["has introduced / reduced","introduced / has reduced","had introduced / reduces","introduces / had reduced","was introducing / was reducing"], a:1, e:"“Two years ago” belli geçmiş zaman olduğu için Simple Past, “since then” ise Present Perfect ister. “has introduced / reduced” “ago” ile Present Perfect kullandığı için yanlıştır."},
  {id:"r-ten-perfect-14", sub:"ten-perfect", from:["tenses-16","tenses-06"], q:"This is the most ambitious space mission that the agency ---- in its sixty-year history.", o:["was ever undertaking","ever undertakes","had ever undertaken","has ever undertaken","will ever undertake"], a:3, e:"“This is the most … that” gibi en üstünlük kalıpları, “It is the first time” gibi, Present Perfect + ever ister. “had ever undertaken” ancak “This was the most …” ile kullanılabilir."},
  {id:"r-ten-perfect-15", sub:"ten-perfect", from:["w2-01","tenses-02"], q:"Since she ---- the director of the institute, she ---- several major reforms to its research policy.", o:["becomes / had introduced","has become / introduced","became / has introduced","had become / introduces","was becoming / will introduce"], a:2, e:"“Since” yan cümlesi Simple Past, ana cümle Present Perfect alır. “has become / introduced” zamanları ters yerleştirir."},
  {id:"r-ten-perfect-16", sub:"ten-perfect", from:["tenses-02","w2-01"], passage:"Plastic was once celebrated as a miracle material: cheap, light and almost indestructible. Yet the very durability that made it so useful is now its greatest drawback. Since large-scale production began in the 1950s, humanity (1) ---- more than eight billion tonnes of plastic, and only a small fraction of it has ever been recycled. Much of the rest has accumulated in landfills and oceans, where it slowly breaks down into tiny particles known as microplastics. Researchers have detected these particles in drinking water, sea salt and even human blood, although their long-term effects on health remain uncertain.", blank:1, q:"(1) numaralı boşluğa uygun ifadeyi seçiniz.", o:["produces","produced","had produced","was producing","has produced"], a:4, e:"“Since large-scale production began in the 1950s” geçmişten bugüne uzanan süreci gösterir ve Present Perfect ister; devamındaki “has ever been recycled” da bunu destekler. “had produced” için geçmişte ikinci bir referans noktası gerekir, metinde yok."},
  {id:"r-ten-perfect-17", sub:"ten-perfect", from:["tenses-06","tenses-11"], q:"Global demand for lithium ---- sharply in recent years as more and more manufacturers ---- to electric vehicle production.", o:["is increasing / had been turning","increased / had turned","had increased / turn","has increased / have turned","was increasing / will turn"], a:3, e:"“in recent years” geçmişten bugüne uzanan dönemi gösterir; iki boşluk da Present Perfect ister. “increased / had turned” geçmişte kalır ve “in recent years” ile uyuşmaz."},
  {id:"r-ten-perfect-18", sub:"ten-perfect", from:["tenses-06","w2-01"], q:"The volcano ---- dormant for nearly 400 years, but seismologists ---- a worrying increase in underground activity over the past few months.", o:["had been / recorded","has been / have recorded","was / had recorded","is / recorded","has been / recorded"], a:1, e:"“for nearly 400 years” (hâlâ uyuyor) ve “over the past few months” bugüne uzanan dönemleri gösterir; iki boşluk da Present Perfect ister. “has been / recorded” ilk boşlukta doğru ama ikinci boşlukta “over the past few months” ile Simple Past kullanır."},
  {id:"r-ten-perfect-19", sub:"ten-perfect", from:["w2-01","tenses-02"], q:"Since the government introduced a tax on sugary drinks, ----.", o:["manufacturers had already begun reducing sugar levels","consumption of such beverages has dropped by almost a quarter","public health officials will monitor children's diets more closely","many families are going to buy fewer soft drinks","the price of fruit juice rose sharply two years ago"], a:1, e:"“Since + Simple Past” yan cümlesinden sonra ana cümle bugüne uzanan sonucu Present Perfect ile verir. “manufacturers had already begun” Past Perfect olduğu için “since” ile bugüne bağlanan anlamı kuramaz."},
  {id:"r-ten-perfect-20", sub:"ten-perfect", from:["tenses-02"], q:"---- the discovery of the Higgs boson in 2012, physicists ---- a number of experiments designed to test the limits of the Standard Model.", o:["For / carried out","Since / have carried out","Until / have carried out","Since / had carried out","Ago / carry out"], a:1, e:"Geçmişteki bir başlangıç noktası (the discovery … in 2012) “since” ile verilir ve ana cümle Present Perfect alır. “For” süre bildiren ifadelerle (for ten years) kullanılır; “Since / had carried out” ise Past Perfect'le bugüne bağlantıyı koparır."},
  {id:"r-ten-perfect-21", sub:"ten-perfect", from:["tenses-06","tenses-02"], q:"Life expectancy in the region ---- by more than ten years over the past half-century, and experts expect it to continue rising.", o:["was increasing","increased","had increased","has increased","increases"], a:3, e:"“over the past half-century” bugüne uzanan dönemi gösterir ve Present Perfect ister; “expect … to continue” da cümleyi şimdiki zamana bağlar. “had increased” geçmişte bir referans noktası gerektirir."},
  {id:"r-ten-perfect-22", sub:"ten-perfect", from:["w2-01","tenses-02"], q:"The two nations ---- diplomatic relations since 1960, and over the years their cooperation ---- to include trade, science and education.", o:["have maintained / has expanded","maintained / expanded","had maintained / expands","are maintaining / had expanded","maintain / was expanded"], a:0, e:"“since 1960” ve “over the years” bugüne uzanan süreçleri gösterir; iki boşluk da Present Perfect ister. “maintained / expanded” Simple Past olduğu için “since” ile kullanılamaz."},
  {id:"r-ten-perfect-23", sub:"ten-perfect", from:["tenses-02"], q:"Halley's Comet ---- from Earth since 1986, but astronomers expect it to return in 2061.", o:["is not visible","was not visible","had not been visible","has not been visible","will not be visible"], a:3, e:"“since 1986” geçmişten bugüne süren durumu gösterir ve Present Perfect ister. “is not visible since” dil bilgisi olarak yanlıştır; “since” ile Simple Present kullanılmaz."},
  {id:"r-ten-perfect-24", sub:"ten-perfect", from:["tenses-06","tenses-11"], q:"So far this year, wildfires ---- more than two million hectares of forest, and the fire season ---- yet.", o:["were destroying / does not end","destroyed / did not end","had destroyed / will not end","destroy / had not ended","have destroyed / has not ended"], a:4, e:"“So far this year” ve “yet” Present Perfect'in tipik zarflarıdır. “destroyed / did not end” bitmiş geçmiş anlatır ve bu zarflarla uyuşmaz."},
  {id:"r-ten-perfect-25", sub:"ten-perfect", from:["tenses-02","w2-01"], q:"Ever since the factory closed, the town's population ---- steadily as young people ---- elsewhere in search of work.", o:["had declined / moved","declined / had moved","has been declining / move","declines / will move","was declining / have been moved"], a:2, e:"“Ever since + Simple Past” ana cümlede bugüne kadar süren bir süreç ister: Present Perfect (Continuous). “had declined / moved” geçmişte ikinci bir referans noktası olmadan Past Perfect kullanır."},
  {id:"r-ten-perfect-26", sub:"ten-perfect", from:["tenses-06"], q:"By now, most European countries ---- plans to phase out coal-fired power stations within the next two decades.", o:["are announced","were announcing","had announced","will announce","have announced"], a:4, e:"“By now” (şimdiye kadar) bugüne kadar tamamlanmış eylemi gösterir ve Present Perfect ister. “had announced” “by then” gibi geçmişteki bir referansla kullanılır."},
  {id:"r-ten-perfect-27", sub:"ten-perfect", from:["tenses-02"], q:"It is ten years since the last major earthquake ---- the region, and experts warn that another one is long overdue.", o:["was striking","has struck","had struck","strikes","struck"], a:4, e:"“It is + süre + since …” kalıbında “since” sonrası tamamlanmış olay Simple Past ile verilir; ana kısım (It is ten years) zaten bugüne bağlıdır. “has struck” bu kalıpta “since” sonrasında kullanılmaz."},
  {id:"r-ten-future-01", sub:"ten-future", from:["tenses-03"], q:"By the end of next year, the company ---- its entire fleet of delivery vans with electric models.", o:["replaced","has replaced","will have replaced","had replaced","is replacing"], a:2, e:"“By + gelecekteki bir zaman” o zamana kadar tamamlanmış olacak eylemi gösterir: Future Perfect. “is replacing” şu an süren bir süreci anlatır, tamamlanma fikrini vermez."},
  {id:"r-ten-future-02", sub:"ten-future", from:["tenses-08"], q:"At noon tomorrow, the astronauts ---- outside the space station to repair a damaged solar panel.", o:["had been working","have worked","will be working","worked","will have worked"], a:2, e:"“At noon tomorrow” gelecekteki belli bir anda sürmekte olacak eylemi gösterir: Future Continuous. “will have worked” o ana kadar tamamlanmayı anlatır, o anda süren çalışmayı değil."},
  {id:"r-ten-future-03", sub:"ten-future", from:["tenses-03","tenses-18"], q:"By 2030, the researchers ---- the snow leopard population in the region for twenty years.", o:["will have been monitoring","have been monitoring","had been monitoring","are monitoring","monitored"], a:0, e:"“By 2030” ve “for twenty years” birlikte gelecekteki bir ana kadar süregelen eylemi gösterir: Future Perfect Continuous. “had been monitoring” geçmişe aittir ve gelecekteki bir tarihle kullanılmaz."},
  {id:"r-ten-future-04", sub:"ten-future", from:["tenses-13"], q:"The flight to Tokyo ---- at 23:45 tonight, so passengers must complete check-in at least an hour beforehand.", o:["had departed","departed","has departed","departs","was departing"], a:3, e:"Tarifeye bağlı gelecek olaylar Simple Present ile anlatılır. “tonight” gelecek anlamı verdiği için geçmiş ve perfect seçenekler elenir."},
  {id:"r-ten-future-05", sub:"ten-future", from:["tenses-18"], q:"By the time the next general election ----, the government ---- most of its major infrastructure projects.", o:["was held / will complete","will be held / has completed","is held / will have completed","has been held / completed","is held / had completed"], a:2, e:"“By the time + Simple Present” kalıbında ana cümle Future Perfect alır. “is held / had completed” ilk boşlukta doğru ama Past Perfect “by the time + past” ile kullanılır."},
  {id:"r-ten-future-06", sub:"ten-future", from:["tenses-08","tenses-13"], q:"Satellite images show that the hurricane ---- the coast within hours, so the authorities have ordered an immediate evacuation.", o:["hit","is going to hit","has hit","had hit","was going to hit"], a:1, e:"Mevcut kanıta dayanan (satellite images show) yakın gelecek tahmini “be going to” ile verilir. “was going to hit” geçmişteki bir beklentiyi anlatır ve “show / have ordered” şimdiki bağlamıyla uyuşmaz."},
  {id:"r-ten-future-07", sub:"ten-future", from:["tenses-08"], q:"This time next month, thousands of students ---- their university entrance exams across the country.", o:["have taken","will be taking","took","had been taking","take"], a:1, e:"“This time next month” gelecekteki belli bir anda sürmekte olacak eylemi gösterir: Future Continuous. “had been taking” geçmişe ait bir yapıdır, gelecekle uyuşmaz."},
  {id:"r-ten-future-08", sub:"ten-future", from:["tenses-18","tenses-03"], q:"By the time the new bridge opens next spring, engineers ---- on the project for more than six years.", o:["are working","have been working","had been working","worked","will have been working"], a:4, e:"“By the time + Simple Present” gelecekteki bir ana kadar olan süreyi, “for more than six years” de süre vurgusunu gösterir: Future Perfect Continuous. “had been working” “by the time + past” ile kullanılır; burada fiil “opens”tur."},
  {id:"r-ten-future-09", sub:"ten-future", from:["tenses-13"], q:"The new trade agreement ---- into force on 1 January, once all member states have ratified it.", o:["was coming","came","has come","had come","is due to come"], a:4, e:"“be due to” resmî olarak planlanmış gelecek olayları anlatır; “once … have ratified” de cümlenin geleceğe dönük olduğunu gösterir. “came” ve perfect seçenekler geçmişi anlattığı için elenir."},
  {id:"r-ten-future-10", sub:"ten-future", from:["tenses-18"], q:"By the time the ambulance reaches the hospital, the surgical team ---- everything for the emergency operation.", o:["has prepared","had prepared","will have prepared","prepared","was preparing"], a:2, e:"“By the time + Simple Present (reaches)” ana cümlede Future Perfect ister. “had prepared” ancak “By the time the ambulance reached” gibi geçmiş zamanlı bir yan cümleyle kullanılır."},
  {id:"r-ten-future-11", sub:"ten-future", from:["tenses-03"], q:"Scientists predict that, within the next few decades, rising sea levels ---- many low-lying islands uninhabitable.", o:["made","will make","had made","have made","were making"], a:1, e:"“predict” ve “within the next few decades” geleceğe dair bir tahmin bildirir; “will” gerekir. “have made” bugüne kadar olmuş bir sonucu anlatır, tahmin anlamını vermez."},
  {id:"r-ten-future-12", sub:"ten-future", from:["tenses-08"], q:"The laboratory will be closed between two and four this afternoon, as the technicians ---- the new equipment during that time.", o:["installed","have installed","had installed","will be installing","will have been installed"], a:3, e:"“between two and four this afternoon … during that time” gelecekteki belli bir zaman aralığında sürecek eylemi gösterir: Future Continuous. “will have been installed” edilgendir ve teknisyenler kuran taraf olduğu için anlamı bozar."},
  {id:"r-ten-future-13", sub:"ten-future", from:["tenses-13"], q:"According to the official programme, the museum's new exhibition ---- on 3 March and runs until the end of June.", o:["opens","opened","has opened","had opened","was opening"], a:0, e:"Resmî programa bağlı etkinlikler Simple Present ile anlatılır; paralel fiil “runs” de bunu doğrular. “opened” geçmiş zaman olduğu için “runs” ile zaman uyumu bozulur."},
  {id:"r-ten-future-14", sub:"ten-future", from:["tenses-08","tenses-03"], q:"By the middle of the century, more than two-thirds of the world's population ---- in cities, according to recent estimates.", o:["will be living","lived","has lived","had been living","was living"], a:0, e:"Gelecekteki bir zamanda süregelen durum Future Continuous ile anlatılabilir; “By the middle of the century” gelecek zamanı gösterir. “had been living” ve “was living” geçmişe ait yapılardır."},
  {id:"r-ten-future-15", sub:"ten-future", from:["tenses-03"], q:"By this time tomorrow, the probe ---- its final orbit around Mars and begun sending data back to Earth.", o:["entered","enters","has entered","had entered","will have entered"], a:4, e:"“By this time tomorrow” gelecekteki bir ana kadar tamamlanmış olacak eylemi gösterir; “and begun” da Future Perfect yapısının (will have entered and begun) devamıdır. “has entered” bugüne bağlanır ve “tomorrow” ile uyuşmaz."},
  {id:"r-ten-future-16", sub:"ten-future", from:["tenses-13"], q:"The minister ---- the new education policy at a press conference next Tuesday; all the arrangements have already been made.", o:["had announced","announced","has announced","is announcing","was announcing"], a:3, e:"Kesinleşmiş planlar ve düzenlemeler (arrangements have been made) için gelecek anlamında Present Continuous kullanılır. “was announcing” geçmişe aittir ve “next Tuesday” ile çelişir."},
  {id:"r-ten-future-17", sub:"ten-future", from:["tenses-18"], q:"By the time the vaccine ---- widely available, the virus ---- to more than fifty countries, experts fear.", o:["became / will spread","will become / has spread","becomes / will have spread","has become / spread","becomes / had spread"], a:2, e:"“By the time + Simple Present” yan cümlede will almaz, ana cümle ise Future Perfect ister. “will become / has spread” will'i zaman bağlacından sonra kullandığı için yanlıştır."},
  {id:"r-ten-future-18", sub:"ten-future", from:["tenses-18","tenses-03"], q:"By the time the space probe reaches Jupiter in 2031, ----.", o:["it will have travelled nearly a billion kilometres","it had travelled nearly a billion kilometres","it has sent back thousands of images","engineers were preparing its final manoeuvre","it travelled through the asteroid belt"], a:0, e:"“By the time + Simple Present” ve “in 2031” gelecek bağlamı kurar; ana cümle Future Perfect ister. “it had travelled” Past Perfect olduğundan ancak geçmiş zamanlı bir “By the time” ile kullanılır."},
  {id:"r-ten-future-19", sub:"ten-future", from:["tenses-18"], q:"When the delegates arrive at the conference centre tomorrow evening, the opening speeches ----, so they will miss them.", o:["will have finished","finish","have finished","had finished","finished"], a:0, e:"Gelecekteki bir andan (arrive tomorrow) önce tamamlanmış olacak eylem Future Perfect ile anlatılır; “will miss them” de bunu doğrular. “finish” konuşmaların varışla aynı anda bittiğini anlatır ve kaçırılmalarını açıklamaz."},
  {id:"r-ten-future-20", sub:"ten-future", from:["tenses-18","tenses-03"], passage:"Engineers are building what will be the world's largest radio telescope, the Square Kilometre Array, at sites in South Africa and Australia. The project is extraordinarily ambitious: once complete, the array will consist of thousands of antennas spread across two continents. Construction is expected to take most of this decade. By the time the telescope becomes fully operational, the partner countries (1) ---- more than two billion euros on it, and the instrument will be able to survey the sky many times faster than any existing facility. Astronomers hope that it will help answer fundamental questions about the origin of galaxies and the nature of dark energy.", blank:1, q:"(1) numaralı boşluğa uygun ifadeyi seçiniz.", o:["will have spent","had spent","have spent","spent","were spending"], a:0, e:"“By the time + Simple Present (becomes)” ana cümlede Future Perfect ister; devamındaki “will be able” da geleceğe işaret eder. “had spent” ancak geçmiş zamanlı “by the time” ile kullanılır."},
  {id:"r-ten-future-21", sub:"ten-future", from:["tenses-03"], q:"The final version of the report ---- to the committee early next week, so any corrections must be submitted by Friday.", o:["was being sent","was sent","has been sent","had been sent","will be sent"], a:4, e:"“early next week” gelecek zamanı gösterir; rapor gönderilen taraf olduğu için edilgen gelecek (will be sent) gerekir. “has been sent” gönderimin çoktan yapıldığını anlatır ve düzeltme isteğiyle çelişir."},
  {id:"r-ten-future-22", sub:"ten-future", from:["tenses-03","tenses-08"], q:"By 2040, the country ---- nuclear power for half a century, making it one of the most experienced operators in the world.", o:["is using","has been using","had been using","will have been using","used"], a:3, e:"“By 2040” ile “for half a century” birlikte gelecekteki bir ana kadar süregelen eylemi gösterir: Future Perfect Continuous. “has been using” bugüne kadar olan süreyi anlatır, 2040 ile uyuşmaz."},
  {id:"r-ten-future-23", sub:"ten-future", from:["tenses-08"], q:"Throughout next summer, volunteers ---- the beaches every weekend to collect plastic waste.", o:["will have been cleaned","cleaned","have cleaned","had cleaned","will be cleaning"], a:4, e:"“Throughout next summer” gelecekte belli bir dönem boyunca sürecek eylemi gösterir; Future Continuous uygundur. “will have been cleaned” edilgendir ve gönüllüler temizleyen taraf olduğu için anlamı bozar."},
  {id:"r-ten-future-24", sub:"ten-future", from:["tenses-03","tenses-18"], q:"The new stadium ---- by the time the Olympic Games open, so the organisers are looking for temporary venues.", o:["is not completed","has not been completed","had not been completed","was not completed","will not have been completed"], a:4, e:"“by the time + Simple Present (open)” ana cümlede Future Perfect ister; stadyum tamamlanan taraf olduğu için edilgen yapı gerekir. “had not been completed” ancak geçmiş zamanlı bir “by the time” ile kullanılır."},
  {id:"r-ten-future-25", sub:"ten-future", from:["tenses-13"], q:"Please take your seats, everyone; the chairperson ---- the results of the vote.", o:["announced","is about to announce","has announced","had announced","was about to announce"], a:1, e:"“be about to” hemen gerçekleşmek üzere olan eylemi anlatır; oturma çağrısı da açıklamanın birazdan yapılacağını gösterir. “was about to announce” geçmişe aittir ve şimdiki bağlamla uyuşmaz."},
  {id:"r-ten-future-26", sub:"ten-future", from:["tenses-03"], q:"The committee ---- its decision by next Friday, so the results will be announced at the weekend.", o:["reached","will have reached","has reached","had reached","was reaching"], a:1, e:"“by next Friday” gelecekteki bir ana kadar tamamlanmayı vurgular: Future Perfect. “has reached” kararın çoktan verildiğini anlatır ve “next Friday” ile çelişir."},
  {id:"r-ten-future-27", sub:"ten-future", from:["tenses-18","tenses-08"], q:"By the time she retires next year, the professor ---- at the university for forty years and ---- more than a hundred doctoral students.", o:["is teaching / supervises","has been teaching / supervised","had been teaching / had supervised","will have been teaching / will have supervised","will teach / has supervised"], a:3, e:"“By the time + Simple Present (retires)” ana cümlede gelecekteki bir ana kadar süreyi (Future Perfect Continuous) ve tamamlanmayı (Future Perfect) ister. “had been teaching / had supervised” geçmiş zamanlı “by the time” ile kullanılır."},
  {id:"r-ten-continuous-01", sub:"ten-continuous", from:["tenses-04"], q:"While the students ---- the chemistry experiment, a small fire ---- out in the corner of the laboratory.", o:["have conducted / breaks","conducted / had broken","were conducting / broke","had conducted / was breaking","are conducting / broke"], a:2, e:"“While” geçmişte süren uzun eylemi Past Continuous ile, araya giren kısa eylemi Simple Past ile verir. “conducted / had broken” yangını deneyden önceye atar ve anlamı bozar."},
  {id:"r-ten-continuous-02", sub:"ten-continuous", from:["tenses-04","tenses-14"], q:"The pilot ---- the plane for landing when one of its engines suddenly ---- fire.", o:["prepared / had caught","was preparing / caught","has prepared / catches","had prepared / was catching","is preparing / caught"], a:1, e:"Süren eylem (hazırlanma) Past Continuous, onu kesen ani olay (suddenly) Simple Past olur. “had prepared / was catching” hazırlığı bitmiş, ani olayı ise süren bir eylem gibi gösterir; sıra bozulur."},
  {id:"r-ten-continuous-03", sub:"ten-continuous", from:["tenses-14"], q:"When the power cut occurred, the surgeons ---- a delicate heart operation, but the backup generators came on immediately.", o:["performed","had performed","have performed","were performing","are performing"], a:3, e:"Elektrik kesildiğinde süren eylem Past Continuous ile verilir. “had performed” ameliyatın kesintiden önce bittiğini ima eder; jeneratörlerin hemen devreye girmesinin önemiyle çelişir."},
  {id:"r-ten-continuous-04", sub:"ten-continuous", from:["tenses-09"], q:"The company ---- losses for three consecutive years when its founder finally ---- to step down.", o:["was made / had agreed","has been making / agrees","had been making / agreed","makes / has agreed","is making / was agreeing"], a:2, e:"“for three consecutive years” geçmişteki bir olaya kadar süregelen eylemi gösterir: Past Perfect Continuous; kesen olay Simple Past olur. “has been making / agrees” bugüne bağlanır ve geçmiş anlatıma uymaz."},
  {id:"r-ten-continuous-05", sub:"ten-continuous", from:["tenses-19"], q:"Doctors ---- the new treatment on volunteers since January, and early results look promising.", o:["have been testing","tested","had been testing","were testing","will test"], a:0, e:"“since January” ve “look promising” geçmişte başlayıp hâlâ süren eylemi gösterir: Present Perfect Continuous. “had been testing” geçmişte bitmiş bir referans noktası ister."},
  {id:"r-ten-continuous-06", sub:"ten-continuous", from:["tenses-14","tenses-04"], q:"When archaeologists analysed it in the laboratory, they found that the ancient jar ---- traces of olive oil and wine.", o:["was containing","contained","has been containing","is containing","had been containing"], a:1, e:"“contain” bir durum fiilidir ve genellikle -ing almaz; bu yüzden Simple Past (contained) gerekir. “was containing” sürekli yapıyı durum fiiline uyguladığı için yanlıştır."},
  {id:"r-ten-continuous-07", sub:"ten-continuous", from:["tenses-14"], q:"According to witnesses, the driver ---- on his mobile phone at the moment the accident happened.", o:["has been talking","has talked","had talked","talks","was talking"], a:4, e:"Kazanın olduğu anda süren eylem Past Continuous ile anlatılır. “had talked” konuşmanın kazadan önce bittiğini ima eder ve “at the moment” ile çelişir."},
  {id:"r-ten-continuous-08", sub:"ten-continuous", from:["tenses-04"], q:"As the scientists ---- the glacier, they noticed that it ---- much faster than predicted.", o:["have observed / melts","observed / had melted","were observing / was melting","had observed / has melted","are observing / melted"], a:2, e:"Gözlem sürerken fark edilen ve o sırada devam eden erime iki boşlukta da Past Continuous ister. “observed / had melted” erimeyi tamamlanmış gibi gösterir; “much faster than predicted” süren bir süreci anlatır."},
  {id:"r-ten-continuous-09", sub:"ten-continuous", from:["tenses-09"], q:"The volunteers ---- for survivors for almost 48 hours when they heard faint voices beneath the rubble.", o:["had been searching","have been searching","were searched","search","are searching"], a:0, e:"Geçmişteki bir olaya (heard) kadar süregelen eylem “for almost 48 hours” ile Past Perfect Continuous alır. “have been searching” bugüne bağlanır ve geçmiş anlatımla uyuşmaz."},
  {id:"r-ten-continuous-10", sub:"ten-continuous", from:["tenses-19"], q:"In recent months, the central bank ---- its interest rate policy closely, as inflation ---- to rise.", o:["reviews / was continuing","reviewed / had continued","had been reviewing / continued","was reviewing / has continued","has been reviewing / continues"], a:4, e:"“In recent months” bugüne kadar süren eylemi gösterir: Present Perfect Continuous; enflasyonun artışı da hâlâ sürdüğü için Simple Present uygundur. “had been reviewing / continued” geçmişte bir referans noktası gerektirir."},
  {id:"r-ten-continuous-11", sub:"ten-continuous", from:["tenses-19","tenses-14"], q:"The main road into the city is closed because engineers ---- the damaged bridge at the moment.", o:["repaired","are repairing","have repaired","had been repairing","were repairing"], a:1, e:"“at the moment” şu anda süren eylemi gösterir: Present Continuous. “have repaired” onarımın bittiğini anlatır; yolun hâlâ kapalı olmasıyla çelişir."},
  {id:"r-ten-continuous-12", sub:"ten-continuous", from:["tenses-09"], q:"The migrating birds ---- south for several days when a sudden storm ---- them far off their usual route.", o:["flew / has blown","have been flying / blow","had been flying / blew","were flown / had blown","fly / was blowing"], a:2, e:"Fırtınaya kadar günlerce süren uçuş Past Perfect Continuous, ani fırtına Simple Past olur. “flew / has blown” geçmiş olayla Present Perfect kullandığı için yanlıştır."},
  {id:"r-ten-continuous-13", sub:"ten-continuous", from:["tenses-04"], q:"While the delegates were debating the final wording of the agreement, ----.", o:["protesters gathered outside the conference centre to demand stronger action","the chairperson will close the session early","a compromise has been reached on most issues","journalists are waiting outside for a statement","the negotiations had ended without an agreement"], a:0, e:"“While + Past Continuous” yan cümlesi, o sırada gerçekleşen eylem için ana cümlede Simple Past ister. “the negotiations had ended” müzakereler hâlâ sürerken bitmiş olmalarını söyleyerek anlamca çelişir."},
  {id:"r-ten-continuous-14", sub:"ten-continuous", from:["tenses-14"], q:"The researchers noticed the error only while they ---- the data for the third time.", o:["have checked","were checking","check","will check","had been checked"], a:1, e:"“while” geçmişte süren eylemi Past Continuous ile verir; fark etme bu süreç sırasında olmuştur. “had been checked” edilgendir ve araştırmacılar kontrol eden taraf olduğu için anlamı bozar."},
  {id:"r-ten-continuous-15", sub:"ten-continuous", from:["tenses-14","tenses-04"], q:"When the fire alarm ----, most of the employees ---- a training session on the second floor.", o:["goes off / were attending","was going off / attended","had gone off / have attended","went off / were attending","went off / had attended"], a:3, e:"“When + Simple Past, Past Continuous” kalıbında alarm kısa eylem, eğitim ise o sırada süren eylemdir. “went off / had attended” eğitimin alarmdan önce bittiğini ima eder; kesilen eylem Past Continuous olmalıdır."},
  {id:"r-ten-continuous-16", sub:"ten-continuous", from:["tenses-19"], q:"The population of the city ---- rapidly at the moment, which ---- serious pressure on housing and public transport.", o:["grew / had put","is growing / is putting","has grown / put","was growing / puts","grows / was putting"], a:1, e:"“at the moment” şu anda süren eylemi gösterir; iki boşluk da Present Continuous ister. “was growing / puts” ilk boşlukta geçmişe kayar ve “at the moment” ile uyuşmaz."},
  {id:"r-ten-continuous-17", sub:"ten-continuous", from:["tenses-14","tenses-04"], passage:"On the morning of 1 November 1755, a powerful earthquake struck the Portuguese capital, Lisbon. It was a religious holiday, and many residents (1) ---- mass in the city's churches when the ground began to shake. Within minutes, much of the city lay in ruins. Those who fled to the waterfront for safety were then swept away by a tsunami, while fires that started in the collapsed buildings burned for days. The disaster killed tens of thousands of people and deeply influenced European thinkers, who began to question long-held beliefs about nature and divine justice.", blank:1, q:"(1) numaralı boşluğa uygun ifadeyi seçiniz.", o:["will be attending","had attended","have attended","attend","were attending"], a:4, e:"Deprem (began to shake) başladığında süren eylem Past Continuous ile verilir. “had attended” ayinin depremden önce bittiğini ima eder; oysa insanlar o sırada kiliselerdeydi."},
  {id:"r-ten-continuous-18", sub:"ten-continuous", from:["tenses-19"], q:"Since the factory opened, residents ---- about the noise and air pollution, but the local council ---- no action so far.", o:["are complaining / takes","complained / took","had been complaining / had taken","have been complaining / has taken","were complaining / has been taken"], a:3, e:"“Since + Simple Past” ile hâlâ süren eylem Present Perfect Continuous, “so far” ile de Present Perfect gerekir. “complained / took” geçmişte kalır ve “since / so far” ile uyuşmaz."},
  {id:"r-ten-continuous-19", sub:"ten-continuous", from:["tenses-04","tenses-14"], q:"The historian ---- a biography of the president when she ---- a collection of his unpublished letters.", o:["was writing / discovered","wrote / had discovered","has written / discovers","had written / was discovering","is writing / discovered"], a:0, e:"Biyografi yazımı süren uzun eylem (Past Continuous), mektupların bulunması ise onu kesen kısa eylemdir (Simple Past). “had written / was discovering” yazımı bitmiş, bulmayı süren bir eylem gibi gösterir."},
  {id:"r-ten-continuous-20", sub:"ten-continuous", from:["tenses-19"], q:"The island ---- to the same family for more than two centuries.", o:["belongs","has been belonging","is belonging","was belonging","has belonged"], a:4, e:"“belong” durum fiilidir, -ing almaz; “for more than two centuries” ile bugüne süren durum Present Perfect ile verilir. “has been belonging” süre vurgusu doğru olsa da durum fiiline sürekli yapı uyguladığı için yanlıştır."},
  {id:"r-ten-continuous-21", sub:"ten-continuous", from:["tenses-14"], q:"When the journalists arrived, the protesters ---- peacefully, but by evening the situation ---- violent.", o:["have marched / was becoming","marched / has become","had marched / becomes","were marching / had become","are marching / became"], a:3, e:"Gazeteciler geldiğinde süren eylem Past Continuous; akşama kadar tamamlanmış değişim ise Past Perfect ile verilir. “had marched / becomes” yürüyüşü bitmiş gösterir ve ikinci boşluk geçmiş anlatıma uymaz."},
  {id:"r-ten-continuous-22", sub:"ten-continuous", from:["tenses-09","tenses-19"], q:"Economists ---- signs of a slowdown for months before the recession was officially declared.", o:["are observing","have been observing","had been observing","observe","will be observing"], a:2, e:"Geçmişteki bir olaydan (was declared) önce aylarca süren eylem Past Perfect Continuous alır. “have been observing” bugüne kadar süren eylem içindir ve geçmişteki ilanla uyuşmaz."},
  {id:"r-ten-continuous-23", sub:"ten-continuous", from:["tenses-19"], q:"Satellite data show that the glacier ---- by about 30 metres a year over the past decade.", o:["has been retreating","retreated","had been retreating","was retreating","retreats"], a:0, e:"“over the past decade” ve “show” bugüne kadar süren bir süreci gösterir: Present Perfect Continuous. “had been retreating” geçmişte bir referans noktası gerektirir."},
  {id:"r-ten-continuous-24", sub:"ten-continuous", from:["tenses-04"], q:"Just as the orchestra ---- the final movement, the lights in the concert hall suddenly ---- out.", o:["is beginning / went","began / had gone","has begun / go","had begun / were going","was beginning / went"], a:4, e:"“Just as” tam o sırada süren eylemi Past Continuous ile, ani olayı (suddenly) Simple Past ile verir. “began / had gone” ışıkların sönmesini daha önceye atar ve “just as” anlamıyla çelişir."},
  {id:"r-ten-continuous-25", sub:"ten-continuous", from:["tenses-09"], q:"The two chemists ---- on the same problem independently for years before they ---- that they had reached identical conclusions.", o:["were worked / have discovered","have been working / discover","had been working / discovered","worked / had discovered","are working / discovered"], a:2, e:"Fark edişten önce yıllarca süren çalışma Past Perfect Continuous, fark ediş Simple Past olur. “worked / had discovered” fark edişi çalışmadan önceye atarak sırayı bozar."},
  {id:"r-ten-continuous-26", sub:"ten-continuous", from:["tenses-14","tenses-04"], q:"When the inspectors ---- the factory unannounced, they found that several machines ---- without the required safety guards.", o:["were visiting / had operated","visited / were operating","have visited / operate","visit / had been operated","had visited / are operating"], a:1, e:"Ziyaret kısa eylemdir (Simple Past); denetçiler geldiğinde makineler o sırada çalışmaktaydı (Past Continuous). “were visiting / had operated” ziyareti uzun eylem, çalışmayı ise bitmiş gibi gösterir."},
  {id:"r-ten-continuous-27", sub:"ten-continuous", from:["tenses-14"], q:"At the time of the survey, most respondents ---- that the economy would improve within a year.", o:["are believing","were believing","have been believing","believed","had been believed"], a:3, e:"“believe” bir durum fiilidir ve genellikle sürekli yapıda kullanılmaz; geçmiş bağlamda Simple Past gerekir. “were believing” durum fiiline -ing eklediği için yanlıştır."},
  {id:"r-ten-timeclause-01", sub:"ten-timeclause", from:["tenses-05"], q:"The factory will not resume production until the safety inspectors ---- their final report.", o:["would submit","will submit","submit","submitted","had submitted"], a:2, e:"Ana cümle gelecek zamanlıdır (will not resume); “until” sonrası gelecek anlamı Simple Present ile verilir. “will submit” zaman bağlacından sonra will kullandığı için elenir."},
  {id:"r-ten-timeclause-02", sub:"ten-timeclause", from:["tenses-10","tenses-20"], q:"As soon as the results of the referendum ---- tomorrow, the prime minister ---- a statement to the nation.", o:["had been announced / made","will be announced / makes","were announced / would make","are announced / will make","are announced / made"], a:3, e:"“as soon as” yan cümlesinde Simple Present (edilgen), ana cümlede will gelir; “tomorrow” gelecek anlamını verir. “will be announced / makes” will'i zaman bağlacının içine koyar."},
  {id:"r-ten-timeclause-03", sub:"ten-timeclause", from:["tenses-05","tenses-20"], q:"Before the new drug ---- available to the public, it ---- a series of rigorous clinical trials.", o:["has been made / had to pass","will be made / has to pass","was made / will have to pass","is made / will have to pass","would be made / passes"], a:3, e:"“Before” zaman bağlacından sonra gelecek anlamı Simple Present ile, ana cümlede ise gelecek zaman (will have to) ile verilir. “will be made / has to pass” zaman bağlacından sonra will kullandığı için yanlıştır."},
  {id:"r-ten-timeclause-04", sub:"ten-timeclause", from:["tenses-15"], q:"Once the researchers ---- enough data, they will publish their findings in an international journal.", o:["will collect","have collected","would collect","had collected","were collecting"], a:1, e:"“Once” ile önce tamamlanması gereken eylem Present Perfect ile verilir; ana cümle will alır. “will collect” zaman bağlacından sonra will kullandığı için yanlıştır."},
  {id:"r-ten-timeclause-05", sub:"ten-timeclause", from:["tenses-10"], q:"The moment the storm ----, rescue teams will begin searching the area for survivors.", o:["passed","will pass","would pass","passes","had passed"], a:3, e:"“The moment” (… anda) bir zaman bağlacıdır; ana cümle gelecek zamanlı olduğunda yan cümlede Simple Present gelir. “will pass” zaman bağlacından sonra will kullanıldığı için yanlıştır."},
  {id:"r-ten-timeclause-06", sub:"ten-timeclause", from:["tenses-20","tenses-15"], q:"By the time today's first-year students ---- their degrees, many of the technologies they are studying now ---- obsolete.", o:["complete / will have become","will complete / have become","completed / will become","have completed / became","complete / had become"], a:0, e:"“By the time + Simple Present” ana cümlede Future Perfect ister. “complete / had become” ilk boşlukta doğru ama Past Perfect geçmiş zamanlı “by the time” ile kullanılır."},
  {id:"r-ten-timeclause-07", sub:"ten-timeclause", from:["w4-06","tenses-20"], q:"As soon as the earthquake warning ----, thousands of residents ---- their homes and headed for open ground.", o:["was issued / left","is issued / will leave","will be issued / leave","has been issued / had left","would be issued / have left"], a:0, e:"“headed” cümlenin geçmişte geçtiğini gösterir; geçmiş bağlamda zaman bağlacı ve ana cümle Simple Past alır. “is issued / will leave” gelecek zamanlıdır ve “headed” ile çelişir."},
  {id:"r-ten-timeclause-08", sub:"ten-timeclause", from:["tenses-05","tenses-15"], q:"Until the investigation report ----, no official statement will be made about the cause of the accident.", o:["was being published","will be published","would be published","had been published","has been published"], a:4, e:"“Until” sonrası gelecek anlamı will olmadan verilir; tamamlanma vurgusu için Present Perfect (edilgen) uygundur. “will be published” zaman bağlacından sonra will kullandığı için yanlıştır."},
  {id:"r-ten-timeclause-09", sub:"ten-timeclause", from:["tenses-05"], q:"The patient cannot be discharged from hospital ---- the doctors are certain that the infection has cleared.", o:["by the time","since","while","as soon as","until"], a:4, e:"Taburculuk ancak enfeksiyonun geçtiğinden emin olununca mümkündür; “until” (… -e kadar / -meden) doğru bağlaçtır. “as soon as” olumsuz ana cümleyle (cannot) anlamsız bir ilişki kurar."},
  {id:"r-ten-timeclause-10", sub:"ten-timeclause", from:["tenses-15"], q:"Once the new metro line has been completed, ----.", o:["commuters could reach the city centre in less than twenty minutes","commuters will be able to reach the city centre in less than twenty minutes","commuters reached the city centre much more quickly","the city had solved its traffic problems","residents have complained about the construction noise for years"], a:1, e:"“Once + Present Perfect” gelecekteki bir tamamlanmayı anlatır; ana cümle will ister. “commuters reached” geçmiş zamanlıdır ve gelecekteki bir durumu anlatamaz."},
  {id:"r-ten-timeclause-11", sub:"ten-timeclause", from:["tenses-15","tenses-20"], q:"After the committee ---- all the applications, it ---- the successful candidates by email.", o:["will review / informed","will have reviewed / informs","reviewed / will inform","had reviewed / informs","has reviewed / will inform"], a:4, e:"“After” yan cümlesinde önce tamamlanacak eylem Present Perfect, ana cümle will alır. “will have reviewed / informs” will'i zaman bağlacının içine koyar ve ana cümlede geleceği vermez."},
  {id:"r-ten-timeclause-12", sub:"ten-timeclause", from:["tenses-10"], q:"Whenever the water level of the river ---- above a critical point, the gates of the dam ---- automatically.", o:["rose / will close","will rise / closed","rises / close","has risen / had closed","would rise / are closing"], a:2, e:"“Whenever” genel geçer, tekrarlanan bir durumu anlatır; iki cümlede de Simple Present kullanılır. “will rise / closed” will'i zaman bağlacından sonra kullanır ve zamanları karıştırır."},
  {id:"r-ten-timeclause-13", sub:"ten-timeclause", from:["tenses-05"], q:"Farmers in the region will have to wait for the rains to arrive ---- they can plant their crops.", o:["unless","since","before","by the time","while"], a:2, e:"Yağmurları bekleme, ekimden önce gelir; “before” doğru zaman ilişkisini kurar. “by the time” tamamlanmayı vurgular ve “can plant” ile anlamlı bir ilişki kurmaz."},
  {id:"r-ten-timeclause-14", sub:"ten-timeclause", from:["tenses-05","w4-06"], q:"The scientists did not announce their discovery until other laboratories ---- their results.", o:["would have confirmed","have confirmed","confirm","will confirm","had confirmed"], a:4, e:"Ana cümle geçmiş zamanlıdır (did not announce); geçmiş bağlamda zaman bağlacından sonra önce tamamlanan eylem Past Perfect alır. “have confirmed” Present Perfect olduğundan geçmiş anlatımla uyuşmaz."},
  {id:"r-ten-timeclause-15", sub:"ten-timeclause", from:["tenses-20"], q:"When the new regulations ---- into force next year, companies ---- to report their carbon emissions annually.", o:["came / would be required","will come / are required","come / will be required","have come / were required","would come / will be required"], a:2, e:"“When” yan cümlesinde Simple Present, ana cümlede will gelir; “next year” gelecek anlamını verir. “will come / are required” will'i yanlış yere, yani zaman bağlacının içine koyar."},
  {id:"r-ten-timeclause-16", sub:"ten-timeclause", from:["w4-06"], q:"By the time the fire brigade arrived at the warehouse, ----.", o:["the flames will have spread to the neighbouring buildings","the flames had already spread to the neighbouring buildings","the flames have been spreading for an hour","the building is being evacuated","the fire will be brought under control"], a:1, e:"Geçmiş zamanlı “By the time” yan cümlesi, ana cümlede daha önce tamamlanan eylem için Past Perfect ister. “will have spread” Future Perfect olup ancak “by the time + present” ile kullanılır."},
  {id:"r-ten-timeclause-17", sub:"ten-timeclause", from:["tenses-10"], q:"The spacecraft will begin sending images back to Earth as soon as it ---- its orbit around Saturn.", o:["enters","will enter","would enter","entered","had entered"], a:0, e:"Ana cümle gelecek zamanlıdır; “as soon as” sonrası Simple Present gelir. “will enter” zaman bağlacından sonra will kullandığı için elenir."},
  {id:"r-ten-timeclause-18", sub:"ten-timeclause", from:["tenses-05","tenses-15"], passage:"Every year, hundreds of thousands of visitors travel to the Galápagos Islands to see their unique wildlife. However, scientists warn that tourism is placing increasing pressure on these fragile ecosystems. In response, the authorities are considering a new system that would limit the number of daily visitors to each island. Under the proposal, no new hotel permits will be issued until a detailed environmental assessment (1) ----. Officials hope that such measures will protect species such as the giant tortoise, which exists nowhere else on Earth, while still allowing local communities to benefit from tourism income.", blank:1, q:"(1) numaralı boşluğa uygun ifadeyi seçiniz.", o:["was completed","will have been completed","would be completed","had been completed","has been completed"], a:4, e:"Ana cümle gelecek zamanlıdır (will be issued); “until” sonrası will kullanılmaz, tamamlanma vurgusu için Present Perfect gelir. “will have been completed” zaman bağlacından sonra will içerdiği için yanlıştır."},
  {id:"r-ten-timeclause-19", sub:"ten-timeclause", from:["tenses-15"], q:"---- the vaccine has been approved by the health authorities, it will be distributed free of charge to all hospitals.", o:["While","Until","Unless","Although","Once"], a:4, e:"“Once” (… -ince) onaydan sonra dağıtımın başlayacağını anlatır ve Present Perfect ile uyumludur. “Unless” onaylanmazsa dağıtılacağı gibi mantıksız bir anlam verir."},
  {id:"r-ten-timeclause-20", sub:"ten-timeclause", from:["tenses-20","tenses-10"], q:"When the old library ---- next year, its entire collection ---- to a modern building on the university campus.", o:["has closed / was moved","will close / is moved","closed / would be moved","closes / will be moved","is closing / had been moved"], a:3, e:"“When” yan cümlesinde Simple Present, ana cümlede edilgen gelecek (will be moved) gelir. “will close / is moved” will'i zaman bağlacına koyar, ana cümlede ise gelecek anlamını vermez."},
  {id:"r-ten-timeclause-21", sub:"ten-timeclause", from:["tenses-05"], q:"The rescue workers will continue searching the collapsed building ---- there is any hope of finding survivors.", o:["as long as","by the time","until","before","once"], a:0, e:"“as long as” (… olduğu sürece) aramanın umut var olduğu süre boyunca devam edeceğini anlatır. “until” umut olana kadar aramak gibi mantıksız bir anlam verir."},
  {id:"r-ten-timeclause-22", sub:"ten-timeclause", from:["w4-06","tenses-20"], q:"The government promised that it ---- taxes as soon as the economy ----.", o:["has lowered / recovers","will lower / will recover","lowered / had recovered","would lower / recovered","would lower / would recover"], a:3, e:"Geçmişteki bir sözün (promised) içindeki gelecek “would” ile verilir; zaman bağlacından sonra ise will/would kullanılmaz, fiil Simple Past'a kayar. “would lower / would recover” would'u zaman bağlacının içine koyduğu için yanlıştır."},
  {id:"r-ten-timeclause-23", sub:"ten-timeclause", from:["tenses-05","tenses-15"], q:"Candidates must not leave the examination hall until the invigilator ---- all the answer sheets.", o:["will collect","has collected","would collect","had collected","will have collected"], a:1, e:"“until” sonrası gelecek anlamı will olmadan verilir; tamamlanma vurgusu için Present Perfect uygundur. “will have collected” zaman bağlacından sonra will içerdiği için yanlıştır."},
  {id:"r-ten-timeclause-24", sub:"ten-timeclause", from:["tenses-20","tenses-05"], q:"No decision about the new airport ---- before the public consultation ---- next spring.", o:["has been taken / will have ended","is taken / will end","was taken / ended","will be taken / ends","would be taken / had ended"], a:3, e:"Ana cümle gelecek zamanlı (edilgen), “before” sonrası ise Simple Present olur; “next spring” gelecek anlamı verir. “is taken / will end” will'i zaman bağlacının içine koyar."},
  {id:"r-ten-timeclause-25", sub:"ten-timeclause", from:["w4-06"], q:"By the time the peace talks resumed, ----.", o:["international observers have been monitoring the ceasefire","the negotiators will have reached a compromise on most issues","both sides had suffered heavy losses on the battlefield","a new round of fighting is breaking out","the mediators will arrive in the capital"], a:2, e:"Geçmiş zamanlı “By the time” yan cümlesi ana cümlede Past Perfect ister. “will have reached” Future Perfect olup ancak “by the time + present” ile kullanılır; “have been monitoring” da geçmiş referansla uyuşmaz."},
  {id:"r-ten-timeclause-26", sub:"ten-timeclause", from:["tenses-10","tenses-05"], q:"Patients should take the medication immediately after they ---- a meal, as it may irritate the stomach otherwise.", o:["will eat","eat","would eat","had eaten","were eating"], a:1, e:"“after” zaman bağlacından sonra genel/gelecek anlam Simple Present ile verilir. “will eat” zaman bağlacından sonra will kullandığı için yanlıştır; “had eaten” ise geçmiş bağlam gerektirir."},
  {id:"r-ten-timeclause-27", sub:"ten-timeclause", from:["tenses-05","tenses-15"], q:"Engineers will not be able to assess the full extent of the damage until the floodwaters ----, which may take several weeks.", o:["have receded","will recede","would recede","had receded","were receding"], a:0, e:"Ana cümle gelecek zamanlıdır; “until” sonrası will gelmez, tamamlanma vurgusu için Present Perfect kullanılır. “will recede” zaman bağlacından sonra will olduğu için yanlıştır."}
);
